import java.util.*;
import java.io.*;

public class e{

	static long mod = 998244353;

	public static void main(String[] args){
		Scanner scanner = new Scanner(System.in);
		long n = scanner.nextLong();
		long m = scanner.nextLong();
		long L = scanner.nextLong();
		long R = scanner.nextLong();
		long h = R-L;

		long e = 0;
		long o = 0;
		if(h % 2 == 1){
			long d = (h+1)/2;
			e = d;
			o = d;
		}
		else{
			long d = h/2;
			e = d;
			o = d;
			if(L % 2 == 1) o++;
			else e++;
		}

		long[][] matrix = {{e, o},{o, e}};
		long[][] powerResult = matrixPower(matrix, m*n);
		long answer = powerResult[0][0];
		if((n*m)%2==1) answer += powerResult[0][1];
		System.out.println(answer%mod);
	}

	static long[][] matrixPower(long[][] base, long exponent){
		if(exponent == 0) return identityMatrix(base.length);
		if(exponent % 2 == 1){
			long[][] temp = matrixPower(base, exponent-1);
			return multiplyMatrices(temp, base);
		}
		long[][] half = matrixPower(base, exponent/2);
		return multiplyMatrices(half, half);
	}

	static long[][] identityMatrix(int size){
		long[][] identity = new long[size][size];
		for(int i=0; i<size; i++) identity[i][i]=1;
		return identity;
	}

	static long[][] multiplyMatrices(long[][] a, long[][] b){
		long[][] result = new long[a.length][b[0].length];
		for(int i=0; i<a.length; i++){
			for(int j=0; j<b[0].length; j++){
				for(int k=0; k<a[0].length; k++){
					result[i][j] += (a[i][k]%mod)*(b[k][j]%mod);
					result[i][j] %= mod;
				}
			}
		}
		return result;
	}
}
